(()=>{
'use strict';
const elements={Li:{name:'Lithium',shells:[2,1],loss:1},Na:{name:'Sodium',shells:[2,8,1],loss:1},K:{name:'Potassium',shells:[2,8,8,1],loss:1},Mg:{name:'Magnesium',shells:[2,8,2],loss:2},Ca:{name:'Calcium',shells:[2,8,8,2],loss:2},Al:{name:'Aluminium',shells:[2,8,3],loss:3},F:{name:'Fluorine',shells:[2,7],gain:1},Cl:{name:'Chlorine',shells:[2,8,7],gain:1},O:{name:'Oxygen',shells:[2,6],gain:2},N:{name:'Nitrogen',shells:[2,5],gain:3}};
const cases=[{donor:'Na',acceptor:'Cl',d:1,a:1,formula:'NaCl'},{donor:'Li',acceptor:'F',d:1,a:1,formula:'LiF'},{donor:'Mg',acceptor:'O',d:1,a:1,formula:'MgO'},{donor:'Ca',acceptor:'O',d:1,a:1,formula:'CaO'},{donor:'K',acceptor:'F',d:1,a:1,formula:'KF'},{donor:'Mg',acceptor:'Cl',d:1,a:2,formula:'MgCl₂'},{donor:'Ca',acceptor:'Cl',d:1,a:2,formula:'CaCl₂'},{donor:'Na',acceptor:'O',d:2,a:1,formula:'Na₂O'},{donor:'Li',acceptor:'O',d:2,a:1,formula:'Li₂O'},{donor:'Al',acceptor:'N',d:1,a:1,formula:'AlN'}];
const total=s=>s.reduce((a,b)=>a+b,0);
const superscript=n=>String(n).replace(/1/g,'¹').replace(/2/g,'²').replace(/3/g,'³');
function charge(symbol){const e=elements[symbol],n=e.loss||e.gain;return (n===1?'':superscript(n))+(e.loss?'⁺':'⁻');}
class Formation{
 constructor(random=Math.random){this.random=random;this.index=-1;this.bag=[];this.next();}
 get current(){return cases[this.index]}
 reset(){this.stage=1;this.latticeOpen=false;this.layers=3;this.direction=null;this.selected=new Set();this.reverse=this.random()<.5;const c=this.current;this.atoms=[...Array.from({length:c.d},()=>({symbol:c.donor,donor:true})),...Array.from({length:c.a},()=>({symbol:c.acceptor,donor:false}))];}
 next(){if(!this.bag.length){this.bag=cases.map((_,i)=>i);for(let i=this.bag.length-1;i>0;i--){const j=Math.floor(this.random()*(i+1));[this.bag[i],this.bag[j]]=[this.bag[j],this.bag[i]];}if(this.bag.at(-1)===this.index)[this.bag[0],this.bag[this.bag.length-1]]=[this.bag.at(-1),this.bag[0]];}this.index=this.bag.pop();this.reset();}
 chooseDirection(symbol){if(this.stage!==1)return;this.direction=symbol;}
 checkDirection(){if(this.direction===this.current.donor){this.stage=2;return true;}return false;}
 electronList(i){const a=this.atoms[i],original=elements[a.symbol].shells;const shells=[...original];if(this.stage===3){shells[shells.length-1]+=a.donor?-elements[a.symbol].loss:elements[a.symbol].gain;while(shells.at(-1)===0)shells.pop();}let id=0;return shells.flatMap((count,shell)=>Array.from({length:count},(_,slot)=>({id:id++,shell,slot,count,shellCount:shells.length,outer:shell===shells.length-1,received:this.stage===3&&!a.donor&&id>total(original)})));}
 toggle(i,id){if(this.stage!==2||!this.electronList(i).some(e=>e.id===id))return;const key=i+':'+id;if(this.selected.has(key))this.selected.delete(key);else this.selected.add(key);}
 transfer(){if(this.stage!==2)return {ok:false,text:'Choose the direction first.'};const required=new Set();this.atoms.forEach((a,i)=>{if(a.donor)this.electronList(i).filter(e=>e.outer).forEach(e=>required.add(i+':'+e.id));});if([...this.selected].some(k=>!required.has(k)))return {ok:false,text:'Select only outer-shell electrons on the atom or atoms that lose electrons.'};if(this.selected.size!==required.size)return {ok:false,text:'Some outer-shell electrons still need to be transferred. Check every donating atom.'};this.stage=3;return {ok:true,text:'Transfer complete. The total number of electrons is unchanged.'};}
}
if(typeof module!=='undefined'&&module.exports)module.exports={Formation,cases,elements,charge};if(typeof document==='undefined')return;
const $=id=>document.getElementById('ion-'+id);if(!$('game'))return;const game=new Formation();
function feedback(text,ok=false){$('feedback').hidden=!text;$('feedback').textContent=text;$('feedback').classList.toggle('success',ok);}
function diagram(){const c=game.current,groups=game.reverse?[false,true]:[true,false];let svg='<title>Select outer-shell electrons to transfer</title>';
groups.forEach((donor,side)=>{const atoms=game.atoms.map((a,i)=>({...a,index:i})).filter(a=>a.donor===donor),symbol=donor?c.donor:c.acceptor;svg+=`<text x="${225+450*side}" y="34" class="ion-element">${elements[symbol].name}</text>`;atoms.forEach((a,j)=>{const x=side*450+(atoms.length===1?225:j===0?115:335),y=185,electrons=game.electronList(a.index),shells=Math.max(...electrons.map(e=>e.shell))+1;for(let s=0;s<shells;s++)svg+=`<circle cx="${x}" cy="${y}" r="${25+s*21}" class="ion-shell"/>`;svg+=`<text x="${x}" y="${y}" class="ion-symbol">${a.symbol}${game.stage===3?charge(a.symbol):''}</text>`;
for(const e of electrons){const angle=(e.slot/e.count*2*Math.PI)-Math.PI/2,radius=25+e.shell*21,ex=x+radius*Math.cos(angle),ey=y+radius*Math.sin(angle),selected=game.selected.has(a.index+':'+e.id)&&game.stage!==3;svg+=`<g data-atom="${a.index}" data-electron="${e.id}" class="ion-electron ${selected?'selected':''} ${e.received?'received':''}" role="button" tabindex="${game.stage===2?0:-1}" aria-disabled="${game.stage!==2}" aria-pressed="${selected}" aria-label="${a.symbol} atom ${j+1}, shell ${e.shell+1}, electron ${e.slot+1}"><circle cx="${ex}" cy="${ey}" r="9" class="ion-electron-hit"/><circle cx="${ex}" cy="${ey}" r="5" class="ion-electron-dot"/></g>`;}
svg+=`<text x="${x}" y="310" class="ion-configuration">${Array.from({length:shells},(_,s)=>electrons.filter(e=>e.shell===s).length).join(', ')}</text>`;});});
svg+='<path d="M450 60 V330" class="ion-divider"/>';return svg;}
function lattice(){const c=game.current,rows=game.layers*2,columns=6;let d=0,a=0,svg='<title>Extended ionic array, schematic ion ratio</title>';
for(let row=0;row<rows;row++)for(let col=0;col<columns;col++){const donor=c.d===c.a?(row+col)%2===0:c.d===2?(row+col)%3!==0:(row+col)%3===0;const symbol=donor?c.donor:c.acceptor,x=110+col*106,y=55+row*64;donor?d++:a++;svg+=`<circle cx="${x}" cy="${y}" r="${donor?20:25}" class="${donor?'ion-lattice-cation':'ion-lattice-anion'}"/><text x="${x}" y="${y}" class="ion-lattice-label">${symbol}${charge(symbol)}</text>`;}
$('lattice-diagram').setAttribute('viewBox','0 0 750 '+(rows*64+45));$('lattice-diagram').innerHTML=svg;$('lattice-count').textContent=d+' '+c.donor+charge(c.donor)+' ions + '+a+' '+c.acceptor+charge(c.acceptor)+' ions · overall charge 0';}
function render(){$('build-lattice').hidden=game.stage!==3;$('build-lattice').textContent=game.latticeOpen?'Hide lattice':'Build the lattice';$('build-lattice').setAttribute('aria-expanded',String(game.latticeOpen));$('lattice').hidden=!game.latticeOpen;if(game.latticeOpen)lattice();$('add-layer').disabled=game.layers>=5;const c=game.current,first=game.reverse?c.acceptor:c.donor,second=game.reverse?c.donor:c.acceptor;$('title').textContent=elements[c.donor].name+' + '+elements[c.acceptor].name;$('direction').disabled=game.stage!==1;for(const [id,from,to] of [['left',first,second],['right',second,first]]){$('dir-'+id).textContent=from+' → '+to;$('dir-'+id).setAttribute('aria-pressed',String(game.direction===from));}
$('step2').textContent=game.stage===3?'2 · Ions formed':'2 · Select the electrons to transfer';$('diagram').innerHTML=diagram();$('selection').textContent=game.stage===1?'Choose the direction to unlock the electrons.':game.stage===2?game.selected.size+' electron'+(game.selected.size===1?'':'s')+' selected':'Transferred electrons are shown in blue.';
$('check').textContent=game.stage===1?'Check direction':game.stage===2?'Transfer selected electrons':'Complete';$('check').disabled=game.stage===1?!game.direction:game.stage===2?!game.selected.size:true;
$('result').hidden=game.stage!==3;$('result').textContent=(c.d>1?c.d+' ':'')+c.donor+charge(c.donor)+' + '+(c.a>1?c.a+' ':'')+c.acceptor+charge(c.acceptor)+' · '+c.formula;}
for(const side of ['left','right'])$('dir-'+side).addEventListener('click',()=>{const first=game.reverse?game.current.acceptor:game.current.donor,second=game.reverse?game.current.donor:game.current.acceptor;game.chooseDirection(side==='left'?first:second);feedback('');render();});
function select(e){const target=e.target.closest('[data-electron]');if(!target)return;const i=Number(target.dataset.atom),id=Number(target.dataset.electron);game.toggle(i,id);feedback('');render();if(e.type==='keydown')$('diagram').querySelector(`[data-atom="${i}"][data-electron="${id}"]`).focus();}
$('diagram').addEventListener('click',select);$('diagram').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select(e);}});
$('check').addEventListener('click',()=>{if(game.stage===1){const ok=game.checkDirection();feedback(ok?'Correct. Select the electrons to transfer.':'Try again. The metal loses electrons and the non-metal gains them.',ok);}else if(game.stage===2){const r=game.transfer();feedback(r.text,r.ok);}render();});
$('build-lattice').addEventListener('click',()=>{if(game.stage!==3)return;game.latticeOpen=!game.latticeOpen;render();});
$('add-layer').addEventListener('click',()=>{if(game.latticeOpen&&game.layers<5){game.layers++;render();}});
$('reset').addEventListener('click',()=>{game.reset();feedback('');render();});$('next').addEventListener('click',()=>{game.next();feedback('');render();});render();
})();
